-- | acceleration config
--
-- The result returned by libinput on setting configuration for a device.
data RiverLibinputAccelConfigV1

-- | Interface metadata for @river_libinput_accel_config_v1@.
riverLibinputAccelConfigV1Interface :: Binding.Interface RiverLibinputAccelConfigV1
riverLibinputAccelConfigV1Interface = Binding.Interface "river_libinput_accel_config_v1" 1

-- | destroy the accel object
--
-- This request indicates that the client will no longer use the accel
--         config object and that it may be safely destroyed.
encodeRiverLibinputAccelConfigV1Destroy :: Binding.RequestEncoder fd
encodeRiverLibinputAccelConfigV1Destroy =
  Binding.RequestEncoder "destroy" (Wire.Opcode 0) 1 True (pure ())

-- | define custom acceleration function
--
-- Defines the acceleration function for a given movement type
--         in an acceleration configuration with custom accel profile.
--
-- @resultValue@: @ArgumentNewId@ argument
-- @typeValue@: @ArgumentUint@ argument
-- @stepValue@: double
-- @pointsValue@: array of doubles
encodeRiverLibinputAccelConfigV1SetPoints :: Wire.ObjectId -> RiverLibinputAccelConfigV1AccelTypeEnum -> ByteString -> ByteString -> Binding.RequestEncoder fd
encodeRiverLibinputAccelConfigV1SetPoints resultValue typeValue stepValue pointsValue =
  Binding.RequestEncoder "set_points" (Wire.Opcode 1) 1 False $ do
    Arguments.putNewId resultValue
    Arguments.putUint (riverLibinputAccelConfigV1AccelTypeEnumValue typeValue)
    Arguments.putArray stepValue
    Arguments.putArray pointsValue

