-- | config application result
--
-- The result returned by libinput on setting configuration for a device.
data RiverLibinputResultV1

-- | Interface metadata for @river_libinput_result_v1@.
riverLibinputResultV1Interface :: Binding.Interface RiverLibinputResultV1
riverLibinputResultV1Interface = Binding.Interface "river_libinput_result_v1" 1

-- | Events emitted by @river_libinput_result_v1@.
data RiverLibinputResultV1Event fd
  = -- | config success
    --
    -- The configuration was successfully applied to the device.
    RiverLibinputResultV1Success
  | -- | config unsupported
    --
    -- The configuration is unsupported by the device and was ignored.
    RiverLibinputResultV1Unsupported
  | -- | config invalid
    --
    -- The configuration is invalid and was ignored.
    RiverLibinputResultV1Invalid
  deriving (Eq, Show)

decodeRiverLibinputResultV1Event :: Wire.Opcode -> Maybe (Binding.EventDecoder fd (RiverLibinputResultV1Event fd))
decodeRiverLibinputResultV1Event (Wire.Opcode 0) =
  Just (Binding.EventDecoder "success" 1 True (pure RiverLibinputResultV1Success) (const []))
decodeRiverLibinputResultV1Event (Wire.Opcode 1) =
  Just (Binding.EventDecoder "unsupported" 1 True (pure RiverLibinputResultV1Unsupported) (const []))
decodeRiverLibinputResultV1Event (Wire.Opcode 2) =
  Just (Binding.EventDecoder "invalid" 1 True (pure RiverLibinputResultV1Invalid) (const []))
decodeRiverLibinputResultV1Event _ = Nothing

